def blocks_of(I,bg=3):
    # find maximal rectangular 2-regions (blocks) separated by bg rows/cols
    H,W=len(I),len(I[0]); seen=set(); bl=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]==2 and (r,c) not in seen:
                # flood fill 4-connectivity
                stack=[(r,c)]; comp=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and I[ny][nx]==2 and (ny,nx) not in seen:
                            stack.append((ny,nx))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                bl.append((min(rs),max(rs),min(cs),max(cs),comp))
    return bl

