    return G
G=load()
def fit(n):
    I,O=G[n+' input'],G[n+' output']; H,W=len(I),len(O[0])
    band_rows={r for r in range(H) if all(I[r][c]==3 for c in range(W))}
    band_cols={c for c in range(W) if all(I[r][c]==3 for r in range(H))}
    vals=[[O[r][c] for c in range(W)] for r in range(H)]
    best=[]
    for ph in range(2,H+1):
        for pc in range(2,W+1):
            votes={}
            for r in range(H):
                for c in range(W):
                    key=(r%ph,c%pc); val=vals[r][c]
                    if (r in band_rows or c in band_cols): continue
                    votes.setdefault(key,set()).add(val)
            ok=all(len(v)==1 for v in votes.values())
            if not ok: continue
            T=dict(votes)
            # reconstruct full O and compare
            recon=[[T.get((r%ph,c%pc),0) for c in range(W)] for r in range(H)]
            mism=sum(1 for r in range(H) for c in range(W) if recon[r][c]!=O[r][c])
            best.append((mism,ph,pc,T))
    best.sort()
    return best[:4]
for n in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    print(n,fit(n))

